graphql.query:
query Ping {
  ping
}

query SystemHealth {
  systemHealth {
    status
    uptime
    version
    timestamp
    metrics {
      cpuUsage
      memoryUsage
      diskUsage
      activeConnections
      queueSize
      averageResponseTime
      errorRate
      throughput
    }
    services {
      name
      status
      responseTime
      lastCheck
      error
    }
  }
}

query EnhancedProjects($filter: EnhancedProjectFilterInput, $sort: ProjectSortInput, $pagination: PaginationInput) {
  enhancedProjects(filter: $filter, sort: $sort, pagination: $pagination) {
    totalCount
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
    edges {
      cursor
      node {
        id
        title
        description
        repoUrl
        platform
        language
        starCount
        forkCount
        tags
        category
        featured
        published
        isPrivate
        popularityScore
        activityLevel
        createdAt
        updatedAt
      }
    }
  }
}

query GetProject($repoUrl: String!) {
  project(repoUrl: $repoUrl) {
    id
    title
    description
    repoUrl
    platform
    language
    languages
    starCount
    forkCount
    tags
    category
    featured
    published
    isPrivate
    markdown
    aiAnalysis {
      id
      description
      complexity
      confidence
      suggestedTags
      category {
        primary
        secondary
        confidence
      }
      technologies {
        languages {
          name
          percentage
        }
        frameworks {
          name
          category
        }
      }
    }
    createdAt
    updatedAt
  }
}

query SearchProjects($query: String!, $filter: EnhancedProjectFilterInput, $pagination: PaginationInput) {
  searchProjects(query: $query, filter: $filter, pagination: $pagination) {
    id
    title
    description
    repoUrl
    language
    starCount
    tags
  }
}

query ProjectStatistics($filter: EnhancedProjectFilterInput) {
  projectStatistics(filter: $filter) {
    totalProjects
    publicProjects
    privateProjects
    featuredProjects
    totalStars
    totalForks
    categoryStats {
      category
      count
      percentage
    }
    languageStats {
      language
      count
      percentage
      totalBytes
    }
    platformStats {
      platform
      count
      percentage
    }
  }
}

query TrendingProjects($timeframe: String!, $limit: Float!) {
  trendingProjects(timeframe: $timeframe, limit: $limit) {
    id
    title
    description
    repoUrl
    starCount
    popularityScore
  }
}

query FeaturedProjects($limit: Float!) {
  featuredProjects(limit: $limit) {
    id
    title
    description
    repoUrl
    starCount
    category
    tags
  }
}

mutation SyncProject($input: SyncProjectInput!) {
  syncProject(input: $input) {
    id
    title
    repoUrl
    syncedAt
  }
}

mutation SyncAllProjects {
  syncAllProjects
}

query PublicProfile($username: String!) {
  publicProfile(username: $username) {
    id
    username
    displayName
    bio
    avatar
    location
    website
    isPublic
    viewCount
    socialLinks {
      platform
      url
    }
    theme {
      primaryColor
      secondaryColor
    }
    stats {
      totalProjects
      publicProjects
      totalStars
      totalForks
    }
  }
}

query SearchProfiles($query: String!, $limit: Float!, $offset: Float!) {
  searchProfiles(query: $query, limit: $limit, offset: $offset) {
    id
    username
    displayName
    bio
    avatar
  }
}

query FeaturedProfiles($limit: Float!) {
  featuredProfiles(limit: $limit) {
    id
    username
    displayName
    avatar
    bio
    stats {
      totalStars
      totalProjects
    }
  }
}

query IsUsernameAvailable($username: String!) {
  isUsernameAvailable(username: $username)
}

mutation CreateProfile($input: CreateProfileInput!) {
  createProfile(input: $input) {
    id
    username
    displayName
    bio
    isPublic
  }
}

mutation UpdateProfile($input: UpdateProfileInput!) {
  updateProfile(input: $input) {
    id
    displayName
    bio
    location
    website
  }
}

