  }
}

graphql.query:
mutation UpdateSocialLinks($socialLinks: [SocialLinkInput!]!) {
  updateSocialLinksGraphQL(socialLinks: $socialLinks) {
    id
    socialLinks {
      platform
      url
      label
    }
  }
}

mutation UpdateProfileTheme($input: ProfileThemeInput!) {
  updateProfileThemeGraphQL(input: $input) {
    id
    theme {
      primaryColor
      secondaryColor
      fontFamily
      backgroundStyle
    }
  }
}

mutation DeleteProfile {
  deleteProfile
}

mutation Signup($email: String!) {
  signup(email: $email) {
    apiKey
    user {
      id
      email
      createdAt
    }
  }
}

mutation ConnectGitHub($userId: String!, $githubId: String!, $githubToken: String!) {
  connectGitHub(userId: $userId, githubId: $githubId, githubToken: $githubToken) {
    id
    email
    githubId
  }
}

mutation RegenerateApiKey($userId: String!) {
  regenerateApiKey(userId: $userId) {
    apiKey
    user {
      id
      email
    }
  }
}

mutation RevokeApiKey($userId: String!) {
  revokeApiKey(userId: $userId) {
    id
    apiKey
  }
}

query ProjectAnalysis($projectId: String!) {
  projectAnalysis(projectId: $projectId) {
    id
    projectId
    description
    complexity
    confidence
    suggestedTags
    category {
      primary
      secondary
      confidence
      tags
    }
    technologies {
      languages {
        name
        percentage
        bytes
        confidence
      }
      frameworks {
        name
        category
        confidence
        version
      }
      databases
      platforms
      buildTools
      testingFrameworks
      tools
    }
    keyFeatures
    model
    version
    analysisDate
    createdAt
  }
}

query UserProjectAnalyses($limit: Float!, $offset: Float!) {
  userProjectAnalyses(limit: $limit, offset: $offset) {
    id
    projectId
    description
    complexity
    confidence
    suggestedTags
    createdAt
  }
}

query RecentAnalyses($limit: Float!) {
  recentAnalyses(limit: $limit) {
    id
    projectId
    description
    complexity
    confidence
    createdAt
  }
}

query EnrichmentJobs($status: String, $limit: Float!, $offset: Float!) {
  enrichmentJobs(status: $status, limit: $limit, offset: $offset) {
    id
    projectId
    status
    progress
    error
    createdAt
    completedAt
  }
}

mutation TriggerEnrichment($input: TriggerEnrichmentInput!) {
  triggerEnrichment(input: $input) {
    id
    projectId
    status
    createdAt
  }
}

mutation BulkTriggerEnrichment($input: BulkEnrichmentInput!) {
  bulkTriggerEnrichment(input: $input) {
    totalJobs
    successfulJobs
    failedJobs
    jobs {
      id
      projectId
      status
    }
  }
}

query AuditSummary($startDate: String, $endDate: String) {
  auditSummary(startDate: $startDate, endDate: $endDate) {
    totalLogs
    totalEvents
    successfulEvents
    successfulActions
    failedActions
    uniqueUsers
    mostCommonAction
    timeRange
  }
}

query SecurityReport($startDate: String!, $endDate: String!, $reportType: ReportType!) {
  securityReport(startDate: $startDate, endDate: $endDate, reportType: $reportType) {
    reportId
    startDate
    endDate
    generatedAt
    failedLoginAttempts {
      total
      uniqueUsers
    }
    rateLimitViolations {
      total
      uniqueUsers
    }
    recommendations
    summary {
      totalSecurityEvents
      criticalEvents
      highSeverityEvents
    }
  }
}

query ActivityReport($startDate: String!, $endDate: String!, $reportType: ReportType!) {
  activityReport(startDate: $startDate, endDate: $endDate, reportType: $reportType) {
    reportId
    startDate
    endDate
    generatedAt
    userActivity {
      totalUsers
      activeUsers
      newUsers
    }
    projectActivity {
      totalProjects
      newProjects
      activeProjects
      syncedProjects
    }
    apiUsage {
      totalCalls
      uniqueEndpoints
      uniqueUsers
    }
  }
}

query SyncHistoryStats($startDate: DateTime, $endDate: DateTime) {
  syncHistoryStats(startDate: $startDate, endDate: $endDate) {
    totalOperations
    successfulOperations
    failedOperations
    successRate
    averageDuration
    operationsByType {
      operation
      count
      successRate
    }
    operationsByPlatform {
      platform
      count
      successRate
    }
    recentFailures {
      id
      operation
      platform
      error
      startedAt
    }
  }
}

query SyncFailureAnalysis($startDate: String, $endDate: String) {
  syncFailureAnalysis(startDate: $startDate, endDate: $endDate) {
    totalFailures
    failuresByPlatform {
      platform
      count
      successRate
    }
    failuresByOperation {
      operation
      count
      successRate
    }
    commonErrors {
      error
      count
      percentage
    }
    failureTrends {
      date
      count
    }
  }
}

mutation StartSyncOperation($input: StartSyncOperationInput!) {
  startSyncOperation(input: $input)
}

mutation CompleteSyncOperation($input: CompleteSyncOperationInput!) {
  completeSyncOperation(input: $input)
}

query SandboxStatus {
  sandboxStatus
}

query SandboxConfig {
  sandboxConfig
}

query CurrentSandboxSession {
  currentSandboxSession {
    id
    userId
    startedAt
    expiresAt
    projectCount
    apiCallCount
    syncOperationCount
    isActive
    metadata
  }
}

query SandboxUsage {
  sandboxUsage {
    projectsUsed
    maxProjects
    apiCallsUsed
    maxApiCalls
    syncOperationsUsed
    maxSyncOperations
    sessionTimeRemaining
  }
}

mutation StartSandboxSession($input: StartSandboxSessionInput!) {
  startSandboxSession(input: $input) {
    id
    userId
    startedAt
    expiresAt
    isActive
  }
}

mutation EndSandboxSession {
  endSandboxSession
}

mutation ResetSandboxData($input: ResetSandboxInput!) {
  resetSandboxData(input: $input)
}
